def calc(expr: str) -> int | str:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(expr[i])
            i += 1

    pos = 0

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def parse_expr():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            value = value + right if op == "+" else value - right
        return value

    def parse_term():
        nonlocal pos
        value = parse_unary()
        while pos < len(tokens) and tokens[pos] in ("*", "/", "%"):
            op = tokens[pos]
            pos += 1
            right = parse_unary()

            if right == 0 and op in ("/", "%"):
                raise ArithmeticError

            if op == "*":
                value *= right
            else:
                quotient = trunc_div(value, right)
                value = quotient if op == "/" else value - right * quotient
        return value

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        value = parse_primary()
        if pos < len(tokens) and tokens[pos] == "^":
            pos += 1
            exponent = parse_unary()
            if exponent < 0:
                raise ArithmeticError
            value = pow(value, exponent)
        return value

    def parse_primary():
        nonlocal pos
        if tokens[pos] == "(":
            pos += 1
            value = parse_expr()
            pos += 1  # ')'
            return value
        value = tokens[pos]
        pos += 1
        return value

    try:
        return parse_expr()
    except ArithmeticError:
        return "error"
